import Component from '@glimmer/component';
import { tracked } from '@glimmer/tracking';
import { on } from '@ember/modifier';
import { fn } from '@ember/helper';

interface Tab { id: string; label: string; }
interface Zone { id: string; label: string; }
interface Plan { id: string; name: string; price: string; desc: string; }
interface Sw { id: string; label: string; desc: string; }

export default class SettingsPage extends Component {
  tabs: Tab[] = [
    { id: 'profile', label: 'Profile' },
    { id: 'notifications', label: 'Notifications' },
    { id: 'billing', label: 'Billing' },
  ];

  zones: Zone[] = [
    { id: 'pst', label: 'Pacific Time (UTC−08:00)' },
    { id: 'mst', label: 'Mountain Time (UTC−07:00)' },
    { id: 'cst', label: 'Central Time (UTC−06:00)' },
    { id: 'est', label: 'Eastern Time (UTC−05:00)' },
    { id: 'utc', label: 'UTC (UTC±00:00)' },
    { id: 'cet', label: 'Central European Time (UTC+01:00)' },
    { id: 'ist', label: 'India Standard Time (UTC+05:30)' },
    { id: 'jst', label: 'Japan Standard Time (UTC+09:00)' },
  ];

  plans: Plan[] = [
    { id: 'free', name: 'Free', price: '$0/mo', desc: '1 project, community support' },
    { id: 'pro', name: 'Pro', price: '$12/mo', desc: 'Unlimited projects, email support' },
    { id: 'team', name: 'Team', price: '$39/mo', desc: 'Shared workspaces, SSO, priority support' },
  ];

  switches: Sw[] = [
    { id: 'email', label: 'Email notifications', desc: 'Weekly summaries and account alerts' },
    { id: 'push', label: 'Push notifications', desc: 'Mentions and replies on your devices' },
    { id: 'digest', label: 'Daily digest', desc: 'One message each morning at 8:00' },
    { id: 'marketing', label: 'Product news', desc: 'Occasional updates about new features' },
  ];

  @tracked selectedTab = 'profile';
  @tracked name = 'Alex Morgan';
  @tracked email = 'alex.morgan@example.com';
  @tracked zone = 'est';
  @tracked plan = 'pro';
  @tracked saved = '';
  @tracked states: Record<string, boolean> = { email: true, push: false, digest: true, marketing: false };

  get currentPlan() {
    return this.plans.find((p) => p.id === this.plan)!;
  }

  isSelected = (id: string) => this.selectedTab === id;
  tabIndex = (id: string) => (this.selectedTab === id ? '0' : '-1');
  isOn = (id: string) => this.states[id];
  isPlan = (id: string) => this.plan === id;
  planTabIndex = (id: string) => (this.plan === id ? '0' : '-1');

  selectTab = (id: string) => {
    this.selectedTab = id;
  };

  onTabKey = (e: KeyboardEvent) => {
    const keys = ['ArrowRight', 'ArrowLeft', 'Home', 'End'];
    if (!keys.includes(e.key)) return;
    e.preventDefault();
    const i = this.tabs.findIndex((t) => t.id === this.selectedTab);
    let n = i;
    if (e.key === 'ArrowRight') n = (i + 1) % this.tabs.length;
    if (e.key === 'ArrowLeft') n = (i - 1 + this.tabs.length) % this.tabs.length;
    if (e.key === 'Home') n = 0;
    if (e.key === 'End') n = this.tabs.length - 1;
    this.selectedTab = this.tabs[n].id;
    const root = (e.currentTarget as HTMLElement);
    (root.querySelectorAll('[role=tab]')[n] as HTMLElement).focus();
  };

  onName = (e: Event) => {
    this.name = (e.target as HTMLInputElement).value;
  };
  onEmail = (e: Event) => {
    this.email = (e.target as HTMLInputElement).value;
  };
  onZone = (e: Event) => {
    this.zone = (e.target as HTMLSelectElement).value;
  };

  toggle = (id: string) => {
    this.states = { ...this.states, [id]: !this.states[id] };
  };

  choosePlan = (id: string) => {
    this.plan = id;
  };

  onPlanKey = (e: KeyboardEvent) => {
    const fwd = ['ArrowRight', 'ArrowDown'];
    const back = ['ArrowLeft', 'ArrowUp'];
    if (!fwd.includes(e.key) && !back.includes(e.key)) return;
    e.preventDefault();
    const i = this.plans.findIndex((p) => p.id === this.plan);
    const n = fwd.includes(e.key)
      ? (i + 1) % this.plans.length
      : (i - 1 + this.plans.length) % this.plans.length;
    this.plan = this.plans[n].id;
    const root = e.currentTarget as HTMLElement;
    (root.querySelectorAll('[role=radio]')[n] as HTMLElement).focus();
  };

  save = (e: Event) => {
    e.preventDefault();
    this.saved = 'Settings saved on 2026-11-14.';
  };

  <template>
    <style>
      .sp { font-family: system-ui, sans-serif; max-width: 640px; margin: 1rem auto; color: #1d2330; }
      .sp h1 { font-size: 1.5rem; margin: 0 0 1rem; }
      .sp [role=tablist] { display: flex; gap: 4px; border-bottom: 2px solid #d5d9e2; }
      .sp [role=tab] { padding: .6rem 1rem; border: 0; background: none; font: inherit; cursor: pointer; border-bottom: 3px solid transparent; margin-bottom: -2px; color: #4a5368; }
      .sp [role=tab][aria-selected=true] { color: #1b4fd8; border-bottom-color: #1b4fd8; font-weight: 600; }
      .sp :focus-visible { outline: 3px solid #f59e0b; outline-offset: 2px; }
      .sp [role=tabpanel] { padding: 1.25rem 0; }
      .sp label.f { display: block; font-weight: 600; margin: 0 0 .9rem; }
      .sp input[type=text], .sp input[type=email], .sp select { display: block; width: 100%; box-sizing: border-box; margin-top: .3rem; padding: .5rem; font: inherit; border: 1px solid #8892a6; border-radius: 6px; }
      .sp .row { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .75rem 0; border-bottom: 1px solid #e6e9f0; }
      .sp .row small { display: block; color: #4a5368; font-weight: 400; }
      .sp [role=switch] { flex: none; width: 46px; height: 26px; border-radius: 13px; border: 2px solid #5b6579; background: #fff; position: relative; cursor: pointer; padding: 0; }
      .sp [role=switch]::after { content: ''; position: absolute; top: 3px; left: 3px; width: 16px; height: 16px; border-radius: 50%; background: #5b6579; transition: transform .15s; }
      .sp [role=switch][aria-checked=true] { background: #1b4fd8; border-color: #1b4fd8; }
      .sp [role=switch][aria-checked=true]::after { background: #fff; transform: translateX(20px); }
      .sp [role=radiogroup] { display: grid; gap: .6rem; }
      .sp [role=radio] { text-align: left; padding: .8rem 1rem; border: 2px solid #c3c9d6; border-radius: 8px; background: #fff; font: inherit; cursor: pointer; display: block; width: 100%; }
      .sp [role=radio][aria-checked=true] { border-color: #1b4fd8; background: #eef3ff; }
      .sp [role=radio] small { display: block; color: #4a5368; }
      .sp .btn { margin-top: 1rem; padding: .55rem 1.2rem; background: #1b4fd8; color: #fff; border: 0; border-radius: 6px; font: inherit; cursor: pointer; }
      .sp .msg { margin-top: .75rem; color: #14633a; }
      .sp fieldset { border: 0; padding: 0; margin: 0; }
      .sp legend { font-weight: 600; margin-bottom: .5rem; padding: 0; }
    </style>

    <div class="sp">
      <h1>Settings</h1>

      <div data-widget="tabs">
        {{! template-lint-disable no-invalid-interactive }}
        <div role="tablist" aria-label="Settings sections" {{on "keydown" this.onTabKey}}>
          {{#each this.tabs as |t|}}
            <button
              type="button"
              role="tab"
              id="tab-{{t.id}}"
              aria-selected={{if (this.isSelected t.id) "true" "false"}}
              aria-controls="panel-{{t.id}}"
              tabindex={{this.tabIndex t.id}}
              {{on "click" (fn this.selectTab t.id)}}
            >{{t.label}}</button>
          {{/each}}
        </div>

        {{#each this.tabs as |t|}}
          <div
            role="tabpanel"
            id="panel-{{t.id}}"
            aria-labelledby="tab-{{t.id}}"
            tabindex="0"
            hidden={{if (this.isSelected t.id) false true}}
          >
            {{#if (this.isSelected t.id)}}
              {{#if (this.isProfile t.id)}}
              {{/if}}
            {{/if}}
          </div>
        {{/each}}
      </div>
    </div>
  </template>
}

