  { value: "America/New_York", label: "Eastern Time (UTC−5)" },
  { value: "Europe/London", label: "London (UTC+0)" },
  { value: "Europe/Berlin", label: "Berlin (UTC+1)" },
  { value: "Asia/Tokyo", label: "Tokyo (UTC+9)" },
]

const notifications = [
  { id: "comments", label: "Comments and mentions", on: true },
  { id: "digest", label: "Weekly digest email", on: false },
  { id: "billing", label: "Billing receipts", on: true },
  { id: "product", label: "Product announcements", on: false },
]

const plans = [
  { value: "free", label: "Free", price: "$0/mo", note: "1 project" },
  { value: "pro", label: "Pro", price: "$12/mo", note: "Unlimited projects" },
  { value: "team", label: "Team", price: "$40/mo", note: "10 seats, SSO" },
]

export default class SettingsPage extends Component {
  @tracked saved = ""

  save = () => {
    this.saved = "Settings saved on 2026-11-14."
  }

  <template>
    <style>
      .settings { max-width: 640px; margin: 2rem auto; font-family: system-ui, sans-serif; color: #1a1a2e; }
      .settings h1 { font-size: 1.5rem; }
      .settings [data-slot="tabs-list"] { display: flex; gap: 4px; border-bottom: 1px solid #ccd; }
