      .settings [data-slot="tabs-tab"][data-selected] { border-bottom-color: #4f46e5; font-weight: 600; }
      .settings [data-slot="tabs-tab"]:focus-visible, .settings button:focus-visible, .settings [role="switch"]:focus-visible, .settings [role="radio"]:focus-visible { outline: 2px solid #4f46e5; outline-offset: 2px; }
      .settings [data-slot="tabs-panel"] { padding: 1rem 0; }
      .settings .row { display: flex; justify-content: space-between; align-items: center; padding: 10px 0; border-bottom: 1px solid #eee; }
      .settings [role="switch"] { width: 40px; height: 22px; border-radius: 11px; border: 0; background: #99a; position: relative; padding: 0; cursor: pointer; }
      .settings [role="switch"][aria-checked="true"] { background: #4f46e5; }
      .settings [data-slot="switch-thumb"] { position: absolute; top: 2px; left: 2px; width: 18px; height: 18px; border-radius: 50%; background: #fff; transition: transform .15s; }
      .settings [role="switch"][aria-checked="true"] [data-slot="switch-thumb"] { transform: translateX(18px); }
      .settings .plan { display: flex; align-items: center; gap: 10px; padding: 10px; border: 1px solid #ccd; border-radius: 8px; margin-bottom: 8px; cursor: pointer; }
      .settings [role="radio"] { width: 18px; height: 18px; border-radius: 50%; border: 2px solid #4f46e5; background: #fff; padding: 0; display: inline-flex; align-items: center; justify-content: center; }
      .settings [data-slot="radio-indicator"] { width: 8px; height: 8px; border-radius: 50%; background: #4f46e5; }
      .settings [data-slot="select-trigger"] { padding: 8px 12px; border: 1px solid #99a; border-radius: 6px; background: #fff; font: inherit; min-width: 260px; text-align: start; }
      .settings [data-slot="select-content"] { background: #fff; border: 1px solid #ccd; border-radius: 6px; padding: 4px; box-shadow: 0 4px 12px #0003; }
      .settings [data-slot="select-item"] { padding: 6px 10px; cursor: pointer; }
      .settings [data-slot="select-item"][data-highlighted] { background: #eef; }
      .settings .save { margin-top: 1rem; padding: 8px 16px; border: 0; border-radius: 6px; background: #4f46e5; color: #fff; font: inherit; cursor: pointer; }
      .settings .label { display: block; margin-bottom: 4px; font-weight: 600; }
    </style>
    <div class="settings">
      <h1>Settings</h1>
      <Tabs @defaultValue="profile" data-widget="tabs" as |t|>
        <t.List aria-label="Settings sections">
          <t.Tab @value="profile">Profile</t.Tab>
          <t.Tab @value="notifications">Notifications</t.Tab>
          <t.Tab @value="billing">Billing</t.Tab>
        </t.List>

        <t.Panel @value="profile">
          <Select @defaultValue="America/New_York" as |s|>
            <s.Label><span class="label">Timezone</span></s.Label>
            <s.Trigger><s.Value /></s.Trigger>
            <s.Content>
              {{#each zones key="value" as |z|}}
                <s.Item @value={{z.value}}>{{z.label}}</s.Item>
              {{/each}}
            </s.Content>
          </Select>
        </t.Panel>

        <t.Panel @value="notifications">
          {{#each notifications key="id" as |n|}}
            <label class="row">
              <span>{{n.label}}</span>
              <Switch @defaultChecked={{n.on}} data-widget="switch" as |s|>
                <s.Thumb />
              </Switch>
            </label>
          {{/each}}
        </t.Panel>

        <t.Panel @value="billing">
