                <g.Radio @value={{p.value}} as |r|>
                  <r.Indicator />
                </g.Radio>
                <span><strong>{{p.label}}</strong> — {{p.price}}<br />{{p.note}}</span>
              </label>
            {{/each}}
          </RadioGroup>
        </t.Panel>
      </Tabs>
      <button type="button" class="save" {{on "click" this.save}}>Save changes</button>
      <p role="status">{{this.saved}}</p>
    </div>
  </template>
}
